referenceSolutions.javascript:
export function solve(values, mapper, limit) {
  const starts = values.map((_, i) => Math.floor(i / limit) * mapper.delay);
  return {
    values: values.map((x) => x * mapper.factor + mapper.offset),
    starts,
    ends: starts.map((t) => t + mapper.delay),
  };
}

